{
 "command": "cat tests/fxdata.py Makefile; grep -rn \"LEDGERLINE_FX_FIXTURES\" --exclude-dir=.git . ; ls tests; find . -path ./.git -prune -o -iname \"*fx*\" -print",
 "description": "Inspect fixture loader and env var references"
}

{
 "mode": "filter",
 "query": "LEDGERLINE_FX_FIXTURES fx fixtures rates",
 "situation": "debugging"
}

{
 "command": "cat docs/testing.md; ls tests/fixtures/fx; LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -15",
 "description": "Read testing docs and rerun with fixture env var"
}

{
 "command": "cat scripts/gen_fx_fixtures.py; cat .gitignore 2>/dev/null",
 "description": "Inspect fixture generator script"
}

{
 "command": "python scripts/gen_fx_fixtures.py && LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -15",
 "description": "Generate FX fixtures and rerun fast tests"
}

{
 "id": "01a0fc66-cd28-70e0-8937-c839b7b2d7e6",
 "content": "Run `make test-fast` for the unit suite (skips the Postgres and network integration tests). `make test` runs everything but needs `docker compose up db` first. The FX tests also need generated fixtures: run `python scripts/gen_fx_fixtures.py` once (output is gitignored) and set `LEDGERLINE_FX_FIXTURES=tests/fixtures/fx`; otherwise test_currency errors with KeyError/FileNotFoundError at setup (see docs/testing.md)."
}

